import React, { useEffect } from 'react';
import { motion } from 'framer-motion';
import Logo from '../components/Logo';
import './Welcome.css';

const Welcome = () => {
  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const fadeInUp = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0 }
  };

  const sections = [
    {
      title: "Welcome to SolarAI",
      content: "Your intelligent solar panel management system that combines cutting-edge AI technology with renewable energy solutions.",
      icon: "🌞"
    },
    {
      title: "Smart Monitoring",
      content: "Real-time monitoring of your solar panel performance with AI-powered analytics to optimize energy production.",
      icon: "📊"
    },
    {
      title: "Predictive Maintenance",
      content: "Advanced algorithms predict potential issues before they occur, ensuring maximum uptime and efficiency.",
      icon: "🔧"
    },
    {
      title: "Energy Optimization",
      content: "AI-driven insights help you make informed decisions about energy usage and storage.",
      icon: "⚡"
    }
  ];

  return (
    <div className="welcome-container">
      <div className="welcome-header">
        <Logo size="large" />
      </div>

      <div className="welcome-content">
        {sections.map((section, index) => (
          <motion.div
            key={index}
            className="welcome-section"
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            transition={{ duration: 0.5, delay: index * 0.2 }}
            variants={fadeInUp}
          >
            <div className="section-icon">{section.icon}</div>
            <h2>{section.title}</h2>
            <p>{section.content}</p>
          </motion.div>
        ))}
      </div>

      <motion.div
        className="welcome-cta"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 2 }}
      >
        <p>Ready to optimize your solar panel system?</p>
        <button className="get-started-btn">Get Started</button>
      </motion.div>
    </div>
  );
};

export default Welcome;
